from pathlib import Path
import shutil
ROOT=Path(__file__).resolve().parent.parent
def put(slug,path,text):
 p=ROOT/'apps'/slug/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
for slug in ['quranic-places-atlas','quranic-parables-studio','understand-salah-lab']:
 shutil.copyfile(ROOT/'apps/quran-concept-atlas/src/lib/library.ts',ROOT/'apps'/slug/'src/lib/library.ts')
put('quranic-places-atlas','src/components/Map.astro','''---
import {places,landPaths} from '../data/content.json';
const {focus=''}=Astro.props;
const markers=places.filter(p=>p.point);
---
<figure class="map-figure"><svg viewBox="0 0 840 560" role="img" aria-labelledby="map-title map-description"><title id="map-title">Selected modern geographical contexts</title><desc id="map-description">Five linked city or heritage markers on a regional land map. Uncertain locations are listed below without invented pins. The numbered legend provides accessible links.</desc><defs><clipPath id="map-clip"><rect width="840" height="560" rx="18"/></clipPath></defs><g clip-path="url(#map-clip)"><rect width="840" height="560" fill="var(--surface-2)"/>{[20,25,30,35,40].map(lat=><g><line x1="0" x2="840" y1={(42-lat)*17.5} y2={(42-lat)*17.5} stroke="var(--line)"/><text x="8" y={(42-lat)*17.5-5} fill="var(--muted)" font-size="12">{lat}°N</text></g>)}<g fill="var(--tint)">{landPaths.map(d=><path d={d}/>)}</g><text x="190" y="215" fill="var(--muted)" font-size="17">Egypt</text><text x="445" y="350" fill="var(--muted)" font-size="19">Arabia</text><text x="270" y="415" fill="var(--muted)" font-size="15" transform="rotate(50 270 415)">Red Sea</text>{markers.map((p,i)=><a href={`/place/${p.id}/`} aria-label={`${p.name}: ${p.kind}`}><title>{p.name} · {p.kind}</title><circle cx={(p.point![0]-20)*21} cy={(42-p.point![1])*17.5} r={focus===p.id?20:15} fill={focus===p.id?'var(--ink)':'var(--accent)'} stroke="var(--surface)" stroke-width="3"/><text x={(p.point![0]-20)*21} y={(42-p.point![1])*17.5+5} text-anchor="middle" fill="var(--bg)" font-size="15" font-weight="700">{i+1}</text></a>)}</g></svg><figcaption><span class="micro">Regional orientation only. Modern city and heritage contexts, not reconstructed event sites. Land geometry: Natural Earth, public domain.</span><ol class="map-legend">{markers.map(p=><li><a href={`/place/${p.id}/`}>{p.name}</a><small>{p.kind}</small></li>)}</ol></figcaption></figure>
<style>.map-figure{margin:0}.map-figure svg{width:100%;height:auto}.map-legend{display:flex;flex-wrap:wrap;gap:12px 28px;padding-left:25px;font-size:.8rem}.map-legend small{display:block;color:var(--muted);font-size:.65rem}.map-figure a:focus-visible circle{stroke:var(--ink);stroke-width:6}</style>
''')
put('quranic-places-atlas','src/pages/index.astro','''---
import Shell from '../layouts/Shell.astro';import Map from '../components/Map.astro';import {places} from '../data/content.json';
---
<Shell title="Quranic Places Atlas"><section class="intro"><span class="eyebrow">Geography with its sources attached</span><h1>Read a place.<br/>See what we can locate.</h1><p>Explore fifteen place references. Follow modern map contexts where evidence supports them, and read unpinned entries without guessing a location.</p></section><section class="panel panel-body"><Map/></section><section class="panel top-gap bottom-gap"><div class="panel-body filters"><label class="field">Find a place<input id="filter" type="search" placeholder="Makkah, Midian, Sinai…"/></label><label class="field">Location evidence<select id="category"><option value="">All entries</option>{[...new Set(places.map(p=>p.kind))].map(k=><option>{k}</option>)}</select></label><label><input id="saved-only" type="checkbox"/> Saved only</label><button class="button secondary" id="export">Copy saved reading list</button><span id="count" class="micro" aria-live="polite"></span></div></section><div class="card-grid">{places.map(p=><article class="panel activity-card" data-item-id={p.id} data-category={p.kind}><span class="eyebrow">{p.kind}</span><h2><a data-reading-link={p.id} href={`/place/${p.id}/`}>{p.name}</a></h2><p>{p.summary}</p><span class="micro">Quran {p.passage.ref}</span><div class="actions"><a class="button" href={`/place/${p.id}/`}>Open entry ↗</a><button class="button secondary" data-save={p.id} aria-pressed="false">Save reading</button></div></article>)}</div><div class="empty" id="empty" hidden><h2>No places match</h2><p>Try another name or change the evidence filter.</p></div><script>import '../lib/library';</script></Shell>
''')
put('quranic-places-atlas','src/pages/place/[id].astro','''---
import Shell from '../../layouts/Shell.astro';import Map from '../../components/Map.astro';import {places} from '../../data/content.json';export function getStaticPaths(){return places.map(place=>({params:{id:place.id},props:{place}}));}const {place}=Astro.props;const p=place.passage;
---
<Shell title={place.name}><a class="back-link" href="/">← All places</a><section class="intro"><span class="eyebrow">{place.kind}</span><h1>{place.name}</h1><p>{place.summary}</p></section><div class="workspace"><section><article class="panel bottom-gap"><div class="panel-head"><h2>Quran {p.ref}</h2><a href={p.translationUrl} target="_blank" rel="noopener noreferrer">Read context ↗</a></div><div class="panel-body"><p class="arabic" lang="ar" dir="rtl">{p.arabic}</p><blockquote class="source-quote">{p.translation}</blockquote><p class="micro">Marmaduke Pickthall</p><a href={place.commentaryUrl} target="_blank" rel="noopener noreferrer">Al-Tafsir al-Muyassar ↗</a><p class="micro">Entry summary is an original concise paraphrase of the cited reading/commentary.</p></div></article>{place.point&&<section class="panel panel-body"><Map focus={place.id}/><a href={place.geoUrl} target="_blank" rel="noopener noreferrer">Coordinate source: {place.geoLabel} ↗</a><p class="micro">Marker: {place.point[1].toFixed(4)}°N, {place.point[0].toFixed(4)}°E. Display precision is not historical site precision.</p></section>}</section><aside class="sidebar"><div class="notice"><h2>What the map can establish</h2><p>{place.note}</p>{!place.point&&<p>No coordinate has been assigned to this entry.</p>}</div><div class="panel panel-body"><button class="button secondary wide" data-save={place.id} aria-pressed="false">Save reading</button><p class="micro top-gap">Bookmarks are optional and stay in this browser for up to 30 days.</p><button class="text-button" data-print>Print this entry</button></div></aside></div><script>import '../../lib/library';</script></Shell>
''')
put('quranic-parables-studio','src/pages/index.astro','''---
import Shell from '../layouts/Shell.astro';import {parables} from '../data/content.json';
---
<Shell title="Quranic Parables Studio"><section class="intro"><span class="eyebrow">Image. Contrast. Reflection.</span><h1 class="editorial">Slow down with<br/>a Quranic comparison.</h1><p>Fourteen readings, each with a diagram to explore, a source-attributed explanation, and a question to take back to the passage.</p></section><section class="panel bottom-gap"><div class="panel-body filters"><label class="field">Find a comparison<input id="filter" type="search" placeholder="Garden, light, tree…"/></label><label class="field">Reading area<select id="category"><option value="">All areas</option>{[...new Set(parables.map(p=>p.area))].map(g=><option>{g}</option>)}</select></label><label><input id="saved-only" type="checkbox"/> Saved only</label><button class="button secondary" id="export">Copy saved reading list</button><span id="count" class="micro" aria-live="polite"></span></div></section><div class="card-grid">{parables.map(p=><article class="panel activity-card" data-item-id={p.id} data-category={p.area}><span class="eyebrow">{p.area} · {p.passage.ref}</span><h2><a data-reading-link={p.id} href={`/parable/${p.id}/`}>{p.title}</a></h2><div class="mini-path" aria-hidden="true"><i></i><span></span><i></i><span></span><i></i></div><p>{p.nodes.map(n=>n.label).join(' → ')}</p><div class="actions"><a class="button" href={`/parable/${p.id}/`}>Explore reading ↗</a><button class="button secondary" data-save={p.id} aria-pressed="false">Save reading</button></div></article>)}</div><div class="empty" id="empty" hidden><h2>No readings match</h2><p>Try another image or choose All areas.</p></div><script>import '../lib/library';</script></Shell><style>.mini-path{display:flex;align-items:center;width:100%;padding:12px 0}.mini-path i{width:15px;height:15px;border:2px solid var(--accent);border-radius:50%}.mini-path span{height:1px;background:var(--line);flex:1}</style>
''')
put('quranic-parables-studio','src/pages/parable/[id].astro','''---
import Shell from '../../layouts/Shell.astro';import {parables} from '../../data/content.json';export function getStaticPaths(){return parables.map(parable=>({params:{id:parable.id},props:{parable}}));}const {parable}=Astro.props;const p=parable.passage;
---
<Shell title={parable.title}><a class="back-link" href="/">← All comparisons</a><section class="intro"><span class="eyebrow">{parable.area} · Quran {p.ref}</span><h1 class="editorial">{parable.title}</h1><p>Begin with the full passage, then use the reading diagram to trace its image or contrast.</p></section><article class="panel bottom-gap"><div class="panel-head"><h2>The passage</h2><a href={p.translationUrl} target="_blank" rel="noopener noreferrer">Read context ↗</a></div><div class="panel-body"><p class="arabic" lang="ar" dir="rtl">{p.arabic}</p><blockquote class="source-quote">{p.translation}</blockquote><p class="micro">Marmaduke Pickthall · Quran {p.ref}</p></div></article><div class="workspace"><section><section class="panel bottom-gap"><div class="panel-head"><h2>Explore the comparison</h2><span class="pill">Reading diagram</span></div><div class="panel-body"><div class="reading-path" role="group" aria-label="Parts of the comparison">{parable.nodes.map((n,i)=><button class="path-node" data-stage={i} aria-pressed={i===0?'true':'false'}><span>{i+1}</span>{n.label}</button>)}</div>{parable.nodes.map((n,i)=><section data-stage-panel={i} class="stage-note"><h3>{n.label}</h3><p>{n.detail}</p></section>)}<p class="micro">An editorial reading aid. Nodes show the named imagery, contrasts, or sequence, not a complete interpretation.</p></div></section><section class="panel panel-body"><span class="eyebrow">Commentary before reflection</span><h2>Read with the source</h2><p>{parable.summary}</p><a href={parable.commentaryUrl} target="_blank" rel="noopener noreferrer">Al-Tafsir al-Muyassar ↗</a>{parable.secondCommentaryUrl&&<p><a href={parable.secondCommentaryUrl} target="_blank" rel="noopener noreferrer">Al-Jalalayn · second commentary ↗</a></p>}<p class="micro">Original concise English paraphrase of the retrieved Arabic commentary.</p><div class="divider"></div><h3>A reflection to try</h3><p>{parable.reflection}</p><label class="field">Your private reading note<textarea id="reflection" rows="4" maxlength="4000" placeholder="What do you notice in the passage?"></textarea></label><p class="micro">Kept in memory for this visit. Copy or download it to keep it.</p><div class="actions"><button class="button secondary" id="copy-note">Copy reading note</button><button class="button secondary" id="download-note">Download note</button></div></section></section><aside class="sidebar"><section class="panel panel-body"><span class="eyebrow">Notice a detail</span><h2>Reading check</h2><p>{parable.question}</p><form id="quiz" data-answer={parable.answer}><fieldset><legend class="sr-only">Choose an answer</legend>{parable.options.map((o,i)=><label class="quiz-option"><input type="radio" name="answer" value={i} required/> {o}</label>)}</fieldset><button class="button top-gap">Check answer</button><p id="feedback" role="status"></p></form></section><section class="panel panel-body"><button class="button secondary wide" data-save={parable.id} aria-pressed="false">Save reading</button><button class="text-button top-gap" data-print>Print reading worksheet</button></section></aside></div><script>import '../../lib/library';import '../../lib/studio';</script></Shell>
<style>.reading-path{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:24px}.path-node{display:grid;justify-items:center;align-content:start;gap:12px;background:var(--surface);border:1px solid var(--line);padding:18px 10px;border-radius:14px;color:var(--ink);font-size:.82rem;min-width:0}.path-node span{display:grid;place-items:center;width:40px;height:40px;border:2px solid var(--accent);border-radius:50%;color:var(--accent-ink)}.path-node[aria-pressed=true]{background:var(--tint);border-color:var(--accent)}.stage-note{border-left:3px solid var(--accent);padding:6px 18px;margin-bottom:20px}.stage-note p{margin:0;color:var(--muted)}@media(max-width:580px){.reading-path{grid-template-columns:1fr}.path-node{display:flex;align-items:center;justify-content:start;text-align:left;padding:12px}}</style>
''')
put('quranic-parables-studio','src/lib/studio.ts','''import {byId,copy} from './utils';
const stages=[...document.querySelectorAll<HTMLButtonElement>('[data-stage]')];function stage(index:string){stages.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.stage===index)));document.querySelectorAll<HTMLElement>('[data-stage-panel]').forEach(p=>p.hidden=p.dataset.stagePanel!==index);}stages.forEach(b=>b.onclick=()=>stage(b.dataset.stage!));stage('0');
const form=byId<HTMLFormElement>('quiz');form.onsubmit=e=>{e.preventDefault();const ok=new FormData(form).get('answer')===form.dataset.answer;byId('feedback').textContent=ok?'That detail matches the passage. Read the source again to see it in context.':'Look back at the passage and try another answer.';};
function note(){return `# ${document.querySelector('h1')?.textContent}\\n${location.origin+location.pathname}\\n\\nMy reflection, not a quotation or scholarly interpretation:\\n${byId<HTMLTextAreaElement>('reflection').value}`;}
byId('copy-note').onclick=()=>copy(note(),'Reading note copied');byId('download-note').onclick=()=>{const url=URL.createObjectURL(new Blob([note()],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='quran-reading-note.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
''')
put('understand-salah-lab','src/pages/index.astro','''---
import Shell from '../layouts/Shell.astro';import {lessons,audio} from '../data/content.json';
---
<Shell title="Understand Salah Lab"><section class="intro"><span class="eyebrow">Attend to the words</span><h1>Know what<br/>you are reciting.</h1><p>Explore fifteen meaning lessons, from the opening takbir to the closing greeting. Read the Arabic, reveal its meaning, and check a detail.</p></section><div class="workspace bottom-gap"><section class="panel panel-body"><span class="eyebrow">Listen locally</span><h2>Al-Fatiha, in full</h2><audio controls preload="none" src={audio.file} aria-label="Al-Fatiha recited by Adeel Shaikh" style="width:100%">Your browser does not support this audio. <a href={audio.file}>Download the recording</a>.</audio><p class="micro">Adeel Shaikh · CC BY-SA 4.0. Full-surah recording, about 50 seconds. <a href={audio.source} target="_blank" rel="noopener noreferrer">Recording and attribution ↗</a></p></section><aside class="sidebar"><div class="notice"><h2>A meaning lab</h2><p>Selected narrated wordings, not a full legal prayer manual. Roman guides are approximate. Local audio is included for Al-Fatiha; the other lessons are text-based.</p><a href="/sources/">Sources and wordings ↗</a></div></aside></div><section class="panel bottom-gap"><div class="panel-body filters"><label class="field">Find a recitation<input id="filter" type="search" placeholder="Bowing, Al-Fatiha, praise…"/></label><label class="field">Part of prayer<select id="category"><option value="">All lessons</option>{[...new Set(lessons.map(l=>l.area))].map(a=><option>{a}</option>)}</select></label><label><input type="checkbox" id="saved-only"/> Saved only</label><button class="button secondary" id="export">Copy saved lesson list</button><span id="count" class="micro" aria-live="polite"></span></div></section><div class="card-grid">{lessons.map(l=><article class="panel activity-card" data-item-id={l.id} data-category={l.area}><span class="eyebrow">{l.area} · {l.audio?'Audio available':'Text lesson'}</span><h2><a data-reading-link={l.id} href={`/lesson/${l.id}/`}>{l.title}</a></h2><p class="arabic" lang="ar" dir="rtl">{l.arabic.length>80?l.arabic.slice(0,80)+'…':l.arabic}</p><div class="actions"><a class="button" href={`/lesson/${l.id}/`}>Open lesson ↗</a><button class="button secondary" data-save={l.id} aria-pressed="false">Save reading</button></div></article>)}</div><div class="empty" id="empty" hidden><h2>No lessons match</h2><p>Try another word or choose All lessons.</p></div><script>import '../lib/library';</script></Shell>
''')
put('understand-salah-lab','src/pages/lesson/[id].astro','''---
import Shell from '../../layouts/Shell.astro';import {lessons,audio} from '../../data/content.json';export function getStaticPaths(){return lessons.map(lesson=>({params:{id:lesson.id},props:{lesson}}));}const {lesson}=Astro.props;const index=lessons.findIndex(l=>l.id===lesson.id);const next=lessons[(index+1)%lessons.length];
---
<Shell title={lesson.title}><a class="back-link" href="/">← All lessons</a><section class="intro"><span class="eyebrow">{lesson.area} · lesson {index+1} of {lessons.length}</span><h1>{lesson.title}</h1><p>Read the Arabic. Recall the meaning before you reveal it.</p></section><div class="workspace"><section><article class="panel bottom-gap"><div class="panel-head"><h2>{lesson.passage?'Quran · '+lesson.passage.ref:'Narrated recitation'}</h2><button class="button secondary small" id="practice" aria-expanded="true" aria-controls="meaning">Hide meaning</button></div><div class="panel-body"><p class="arabic" lang="ar" dir="rtl">{lesson.arabic}</p>{lesson.transliteration&&<p class="micro">Approximate Roman guide: {lesson.transliteration}</p>}<div id="meaning"><span class="eyebrow">{lesson.passage?'Marmaduke Pickthall':'Our concise English rendering'}</span><blockquote class="source-quote">{lesson.meaning}</blockquote></div>{lesson.note&&<p class="micro">{lesson.note}</p>}{lesson.passage&&<p><a href={lesson.passage.translationUrl} target="_blank" rel="noopener noreferrer">Quran {lesson.passage.ref} · read context ↗</a></p>}{lesson.commentaryUrl&&<p><a href={lesson.commentaryUrl} target="_blank" rel="noopener noreferrer">Al-Tafsir al-Muyassar ↗</a></p>}{lesson.sources.map(s=><p><a href={s.url} target="_blank" rel="noopener noreferrer">{s.label} ↗</a></p>)}</div></article>{lesson.audio&&<section class="panel panel-body"><h2>Listen to the whole surah</h2><audio id="recitation" controls preload="metadata" src={audio.file} aria-label="Full Al-Fatiha recording by Adeel Shaikh" style="width:100%"></audio><div class="filters top-gap"><label class="field">Playback speed<select id="speed"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></label><label><input id="loop" type="checkbox"/> Repeat full surah</label></div><p id="audio-error" class="micro" hidden>Audio could not load. Try reloading or download the local recording.</p><p class="micro">This plays Al-Fatiha in full, not an isolated ayah. Adeel Shaikh · <a href={audio.licenseUrl}>CC BY-SA 4.0</a>. <a href={audio.source}>Source recording</a> · <a href={audio.file} download>Download audio</a></p></section>}</section><aside class="sidebar"><section class="panel panel-body"><span class="eyebrow">Check understanding</span><h2>One detail</h2><p>{lesson.question}</p><form id="quiz" data-answer={lesson.answer}><fieldset><legend class="sr-only">Choose an answer</legend>{lesson.options.map((o,i)=><label class="quiz-option"><input type="radio" name="answer" value={i} required/> {o}</label>)}</fieldset><button class="button top-gap">Check answer</button><p id="feedback" role="status"></p></form></section><section class="panel panel-body"><button class="button secondary wide" data-save={lesson.id} aria-pressed="false">Save reading</button><a class="button secondary wide top-gap" href={`/lesson/${next.id}/`}>Next: {next.title} ↗</a><button class="text-button top-gap" data-print>Print this lesson</button></section></aside></div><script>import '../../lib/library';import '../../lib/lesson';</script></Shell>
''')
put('understand-salah-lab','src/lib/lesson.ts','''import {byId} from './utils';
byId('practice').onclick=()=>{const panel=byId('meaning');panel.hidden=!panel.hidden;byId('practice').textContent=panel.hidden?'Reveal meaning':'Hide meaning';byId('practice').setAttribute('aria-expanded',String(!panel.hidden));};
const form=byId<HTMLFormElement>('quiz');form.onsubmit=e=>{e.preventDefault();const ok=new FormData(form).get('answer')===form.dataset.answer;byId('feedback').textContent=ok?'That matches the wording. Read it again with the meaning in mind.':'Reveal the meaning, read it again, and try another answer.';};
const player=document.querySelector<HTMLAudioElement>('#recitation');if(player){byId('speed').onchange=()=>{player.playbackRate=Number(byId<HTMLSelectElement>('speed').value);};byId('loop').onchange=()=>{player.loop=byId<HTMLInputElement>('loop').checked;};player.addEventListener('error',()=>{byId('audio-error').hidden=false;});}
''')
for slug in ['quranic-places-atlas','quranic-parables-studio','understand-salah-lab']:
 p=ROOT/'apps'/slug/'src/styles/global.css'
 with p.open('a',encoding='utf-8') as f:f.write('\n.quiz-option{display:flex;align-items:start;gap:10px;padding:11px 0;font-size:.83rem;line-height:1.6}.quiz-option input{margin-top:5px;flex-shrink:0}audio{border-radius:10px}.activity-card .arabic{width:100%;font-size:1.45rem;line-height:1.9}.panel-head a{font-size:.8rem}\n')
